"""Camera/proprioception-driven controller for the single VLABench episode.
No simulator imports or object state. Every submitted trajectory is saved for replay.
Usage: python gen.py obs | move X Y Z [--orientation front|down] [--seconds 4]
       python gen.py grip WIDTH | replay
"""
import argparse, json, os, time
from pathlib import Path
import numpy as np
from scipy.spatial.transform import Rotation
from scipy.optimize import least_squares
from rcb_client import Robot

ROOT=Path('/app/output')
LIMITS=np.array([[-2.8973,2.8973],[-1.7628,1.7628],[-2.8973,2.8973],[-3.0718,-.0698],[-2.8973,2.8973],[-.0175,3.7525],[-2.8973,2.8973]])
ORIGINS=[([0,0,.333],[0,0,0]),([0,0,0],[-np.pi/2,0,0]),([0,-.316,0],[np.pi/2,0,0]),([.0825,0,0],[np.pi/2,0,0]),([-.0825,.384,0],[-np.pi/2,0,0]),([0,0,0],[np.pi/2,0,0]),([.088,0,0],[np.pi/2,0,0])]
FRONT=np.array([[0,1,0],[0,0,1],[1,0,0.]])
DOWN=np.diag([1.,-1.,-1.])

def transform(xyz,rot):
    t=np.eye(4);t[:3,:3]=rot;t[:3,3]=xyz;return t
ORIGINS=[transform(x,Rotation.from_euler('xyz',r).as_matrix()) for x,r in ORIGINS]
BASE=transform([0,-.4,.78],Rotation.from_euler('z',np.pi/2).as_matrix())
END=transform([0,0,.200],Rotation.from_euler('z',-np.pi/4).as_matrix())

def fk(q):
    t=BASE.copy()
    for a,v in zip(ORIGINS,q):
        t=t@a@transform([0,0,0],Rotation.from_euler('z',v).as_matrix())
    return t@END

def ik(pos,rot,seed):
    def err(q):
        t=fk(q)
        return np.r_[10*(t[:3,3]-pos),Rotation.from_matrix(rot@t[:3,:3].T).as_rotvec(),.003*(q-seed)]
    sol=least_squares(err,np.clip(seed,LIMITS[:,0]+1e-6,LIMITS[:,1]-1e-6),bounds=(LIMITS[:,0]+1e-5,LIMITS[:,1]-1e-5),max_nfev=300,xtol=1e-11,ftol=1e-11,gtol=1e-11)
    t=fk(sol.x);pe=np.linalg.norm(t[:3,3]-pos);re=np.linalg.norm(Rotation.from_matrix(rot@t[:3,:3].T).as_rotvec())
    if pe>.006 or re>.04: raise RuntimeError(f'IK residual position={pe}, rotation={re}')
    return sol.x

class Controller:
    def __init__(self): self.r=Robot()
    def save(self,res,label):
        idx=res.meta['calls'];out=ROOT/f'{idx:03d}_{label}';res.save(str(out))
        (ROOT/'latest.json').write_text(json.dumps({'dir':str(out),'meta':res.meta}))
        print(json.dumps({'dir':str(out),'steps':res.meta['control_steps'],'done':res.done,'reason':res.meta.get('reason'),'proprio':res.meta['proprio']['now']},indent=2))
        return res
    def obs(self):return self.save(self.r.get_obs(include_depth=True,video='none'),'obs')
    def state(self):return np.array(self.r.get_obs(cameras=[],video='none').meta['proprio']['now'])
    def submit(self,a,label):
        a=np.asarray(a,float)
        assert np.all(a[:,:7]>=LIMITS[:,0]) and np.all(a[:,:7]<=LIMITS[:,1])
        rec={'action_type':'joint_position','actions':a.tolist(),'dt':.1,'interpolate':'linear','note':label}
        with open(ROOT/'commands.jsonl','a') as f:f.write(json.dumps(rec)+'\n')
        return self.save(self.r.submit(**rec,cameras=['forward','left','right','wrist'],video='none',include_depth=True),label)
    def move(self,pos,rot=None,seconds=4.,width=None):
        p=self.state();q=p[:7];t=fk(q);start=t[:3,3];r0=Rotation.from_quat(p[[20,21,22,19]]).as_matrix()
        if rot is None: rot=r0
        delta=Rotation.from_matrix(rot@r0.T).as_rotvec();n=int(round(seconds/.1));a=[]
        finger=p[30:32] if width is None else [width,width]
        for k in range(1,n+1):
            u=k/n;u=u*u*(3-2*u)
            rp=Rotation.from_rotvec(u*delta).as_matrix()@r0
            q=ik((1-u)*start+u*np.array(pos),rp,q)
            a.append(np.r_[q,finger])
        a.extend([a[-1]]*10)
        return self.submit(a,'move')
    def grip(self,width,seconds=2.):
        p=self.state();a=np.tile(np.r_[p[23:30],width,width],(int(seconds/.1),1));return self.submit(a,'grip')

def main():
    ap=argparse.ArgumentParser();ap.add_argument('command',choices=['obs','move','grip','replay']);ap.add_argument('values',nargs='*',type=float);ap.add_argument('--orientation',choices=['front','down','keep'],default='keep');ap.add_argument('--seconds',type=float,default=4);ap.add_argument('--width',type=float)
    args=ap.parse_args();c=Controller()
    if args.command=='obs':c.obs()
    elif args.command=='move':c.move(args.values,{'front':FRONT,'down':DOWN,'keep':None}[args.orientation],args.seconds,args.width)
    elif args.command=='grip':c.grip(args.values[0])
    else:
        for line in (ROOT/'commands.jsonl').read_text().splitlines():
            rec=json.loads(line);res=c.r.submit(**rec,cameras=[],video='none')
            if res.done:print(res.meta);break
if __name__=='__main__':main()
